INSERT INTO world.QuestSpeeches (QuestId, SpeechKind, LineIndex, Text, Color)
VALUES (146, 0, 2, N'gardens in China? Ugh, but right now, the area', 1),
       (146, 0, 3, N'is invaded by the Red Flute Maidens. If they', 1),
       (146, 0, 4, N'are allowed to remain there, very soon the herbs', 1),
       (146, 0, 5, N'will be in short supply. This will greatly affect', 1),
       (146, 0, 6, N'us all. So, please go and kill 10', 1),
       (146, 0, 7, N'Red Flute Maidens? ', 1),
       (146, 0, 8, N'They''re hiding in Chikurin Ravine, but be ', 2),
       (146, 0, 9, N'careful, they can attack over distance.', 2),
       (146, 1, 0, N'Red Flute Maidens can attack over a distance', 1),
       (146, 1, 1, N'Go and kill 10 of them, please,', 1),
       (146, 1, 2, N'The herb supply must not be affected!', 1),
       (146, 1, 5, N'** Reference Notes **', 34),
       (146, 1, 6, N'Red Flute Maidens hang around all of', 34),
       (146, 1, 7, N'Chikurin Ravine. They attack by using the tone of', 34),
       (146, 1, 8, N'a flute over a long range, so be careful!', 34),
       (146, 7, 0, N'Wow, I''m sorry we have to trouble you so much,', 1),
       (146, 7, 1, N'but thanks to your efforts. We can have the', 1),
       (146, 7, 2, N'Chikurin Ravine supply again!', 1),
       (146, 7, 3, N'Thanks, I owe you a lot!', 1),
       (146, 8, 0, N'Ah, I have it, now get lost.', 1),
       (146, 8, 1, N'I will write this into the report.', 1),
       (146, 9, 0, N'Come to me. The Red Flute Maidens', 1),
       (146, 9, 1, N'have invaded the Chikurin Ravine.', 1),
       (146, 9, 2, N'Our herb supplies are affected!', 1),
