       (154, 7, 2, N'How about it, you wanna try? Aha, just kidding.', 1),
       (154, 7, 3, N'I''m going to analyze it, sorry to have troubled', 1),
       (154, 7, 4, N'you.', 1),
       (154, 9, 0, N'Come to me. ', 1),
       (154, 9, 1, N'I need you to get me the Violet Pill, thanks.', 1),
       (155, 0, 0, N'Since you killed Kitfo Warrior, it seems', 1),
       (155, 0, 1, N'their Chief is wanting to take revenge on you.', 1),
       (155, 0, 2, N'Oh well, it''s just a bull anyway, haha.', 1),
