       (260, 0, 8, N'reached Togata Fortress. Please! You must stop', 1),
       (260, 0, 9, N'him.', 1),
       (260, 1, 0, N'This creature has left the Daseba Temple,', 1),
       (260, 1, 1, N'past the Maze Hole, and now has reached', 1),
       (260, 1, 2, N'Togata Fortress. You must stop him, please.', 1),
