       (390, 1, 5, N'** Reference Notes **', 30),
       (390, 1, 6, N'Elephantine Herald coordinates', 34),
       (390, 1, 7, N'- Temple of Shiko North <3522, 723>', 34),
       (390, 7, 0, N'Although the Elephantine Herald was not killed,', 1),
       (390, 7, 1, N'we did manage to slow it down. We can take this ', 1),
       (390, 7, 2, N'as a success. Very good results, indeed!', 1),
